const chatId = '5759927190';
const executionId = String($execution.id ?? Date.now());
const timestamp = Date.now();
const payload = {
  jobId: executionId + '-' + timestamp,
  chatId,
  requestId: 'acid-ghost-test-' + executionId + '-' + timestamp,
  operation: 'download',
  queries: ['Acid Ghost - Epilogue'],
  metadataQuery: 'Acid Ghost - Epilogue',
  spotifyUrl: 'https://open.spotify.com/track/7ChiNLVsA0UYz7iHoZdLKA',
  format: 'm4a',
  delivery: 'individual',
  options: {
    audioProviders: [],
    lyricsProviders: ['musixmatch', 'genius', 'synced', 'azlyrics'],
    overwrite: 'skip', restrict: 'strict', threads: 4, maxRetries: 2,
    skipAlbumArt: true, generateLrc: false, preload: false,
  },
};
return { chatId, payloadB64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64') };

const raw = String($json.stdout ?? '').trim();
let result;
try { result = JSON.parse(raw); } catch { throw new Error(String($json.stderr ?? '').trim() || raw || 'The downloader returned invalid JSON'); }
if (!Array.isArray(result.files) || result.files.length !== 1 || !result.jobDirectory) throw new Error(String(result.error ?? result.message ?? 'Epilogue produced no audio file'));
const track = result.tracks?.[0] ?? {};
return {
  chatId: '5759927190', jobDirectory: String(result.jobDirectory), remotePath: String(result.files[0]),
  fileName: String(track.fileName ?? 'Acid_Ghost-Epilogue.m4a'), title: String(track.title ?? 'Epilogue'),
  artist: String(track.artist ?? 'Acid Ghost'), album: String(track.album ?? "It's Just Music"),
  year: String(track.year ?? '2024'), trackNumber: Number(track.trackNumber) || 1,
  trackCount: Number(track.trackCount) || 9, publisher: String(track.publisher ?? 'Acid Ghost Inc.'),
  spotifyUrl: String(track.spotifyUrl ?? 'https://open.spotify.com/track/7ChiNLVsA0UYz7iHoZdLKA'),
  duration: Number(track.duration) || 0,
};

let lookup;
try { lookup = JSON.parse(String($json.stdout ?? '').trim()); } catch { lookup = {}; }
const base = $('Parse Acid Ghost result').first().json;
const track = { ...base, lyrics: String(lookup.lyrics ?? '') };
const CAPTION_LIMIT = 1024;
const escapeHtml = (value) => String(value ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
const escapeAttribute = (value) => escapeHtml(value).replaceAll('"', '&quot;').replaceAll("'", '&apos;');
const lyrics = String(track.lyrics ?? '').replace(/\r/g, '').replace(/\[(?:\d{1,2}:)?\d{1,2}:\d{2}(?:[.:]\d{1,3})?\]\s*/g, '').trim();
const header = '<code>' + escapeHtml(track.title) + '</code> — <b>' + escapeHtml(track.artist) + '</b>\n<b><i>' + escapeHtml(track.album) + '</i></b>\n<i>[' + escapeHtml(track.year) + ' · ' + track.trackNumber + '/' + track.trackCount + ' · ' + escapeHtml(track.publisher) + ']</i>';
const footer = '<a href="' + escapeAttribute(track.spotifyUrl) + '">Spotify</a>';
const available = Math.max(0, CAPTION_LIMIT - header.replace(/<[^>]+>/g, '').length - footer.length - 4);
const clipped = lyrics.length > available ? lyrics.slice(0, Math.max(0, available - 2)).trimEnd() + '…' : lyrics;
return { ...track, caption: header + (clipped ? '\n<blockquote expandable>' + escapeHtml(clipped) + '</blockquote>' : '') + '\n' + footer };
